<?php
if (!isset($chatController) || !isset($userData)) return;

$userId = $userData->id ?? null;
if (!$userId) return;

$isChatOpen = $_SESSION['chat_open'] ?? false;



if (isset($_GET['openChat'])) {
    $_SESSION['chat_open'] = true;
    exit;
}

if (isset($_GET['closeChat'])) {
    unset($_SESSION['chat_open']);
    exit;
}

// 1. AJAX Endpoint cho User lấy lịch sử tin nhắn
if (isset($_GET['ajax_get_user_chat']) && $userId) {
    header('Content-Type: application/json');
    $messages = $chatController->getChatHistory($userId);
    echo json_encode($messages);
    exit;
}

// 2. AJAX Endpoint cho User gửi tin nhắn
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['ajax_send_user_chat']) && $userId) {
    header('Content-Type: application/json');
    $message = trim($_POST['message'] ?? '');
    if ($message !== '') {
        $result = $chatController->sendMessage($userId, ['sender_role' => 'user'], $message);
        if ($result['success']) {
            $_SESSION['chat_open'] = true;
            echo json_encode(['success' => true, 'time' => date('H:i d/m/Y')]);
        } else {
            echo json_encode(['success' => false]);
        }
    } else {
        echo json_encode(['success' => false]);
    }
    exit;
}

// 3. Fallback POST thường nếu không dùng JS
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['message']) && !isset($_POST['ajax_send_user_chat']) && $userId) {
    $message = trim($_POST['message']);
    if ($message !== '') {
        $result = $chatController->sendMessage($userId, ['sender_role' => 'user'], $message);
        if ($result['success']) {
            $_SESSION['chat_open'] = true;
            echo '<meta http-equiv="refresh" content="0">';
        }
    }
}

$messages = $chatController->getChatHistory($userId);
?>

<div id="chat-form" class="chat-box <?= $isChatOpen ? '' : 'hidden' ?>">
    <div class="p-2 bg-primary text-white d-flex justify-content-between align-items-center" style="border-radius: 8px 8px 0 0;">
        <div class="d-flex align-items-center">
            <img src="data:image/jpeg;base64," alt="Logo" style="width: 36px; height: 36px; border-radius: 50%; margin-right: 10px;">
            <div style="line-height: 1;">
                <div style="font-weight: bold; font-size: 18px; margin-bottom: 5px;">GARENA</div>
                <div style="font-size: 13px;">Chat với chúng tôi</div>
            </div>
        </div>
        <i id="chat-close" class="bi bi-x-lg" style="cursor: pointer; font-size: 18px;"></i>
    </div>


    <div id="chat-content" class="p-2 overflow-auto flex-grow-1" style="background: #f8f9fa;">
        <?php foreach ($messages as $msg) { ?>
            <?php if ($msg->from === 'admin') { ?>
                <div class="d-flex align-items-start mb-2 flex-column">
                    <div class="d-flex" style="max-width: 80%;">
                        <img src="data:image/jpeg;base64,"
                            class="rounded-circle me-2" style="width: 30px; height: 30px;">
                        <div class="p-2 rounded bg-light border">
                            <?= htmlspecialchars($msg->message) ?>
                        </div>
                    </div>
                    <div class="small text-muted" style="margin-left: 40px;"><?= $msg->time ?></div>
                </div>
            <?php } else { ?>
                <div class="mb-2 text-end">
                    <div class="d-inline-block p-2 rounded bg-primary text-white" style="max-width: 80%; word-break: break-word; text-align: left;">
                        <?= htmlspecialchars($msg->message) ?>
                    </div>
                    <div class="small text-muted"><?= $msg->time ?></div>
                </div>
            <?php } ?>
        <?php } ?>
    </div>


    <form id="user-chat-input-form" method="POST" class="p-2 border-top d-flex align-items-center">
        <input type="text" id="user-chat-input" name="message" class="form-control me-2" style="border: none; box-shadow: none; outline: none;" placeholder="Nhập tin nhắn..." required autocomplete="off">
        <button type="submit" class="btn">
            <i class="bi bi-send text-primary fs-4"></i>
        </button>
    </form>
</div>

<script>
    document.addEventListener("DOMContentLoaded", function() {
        const chatForm = document.getElementById("chat-form");
        const chatContent = document.getElementById("chat-content");
        const userForm = document.getElementById("user-chat-input-form");
        const userInput = document.getElementById("user-chat-input");

        const closeBtn = document.getElementById("chat-close");
        if (closeBtn && chatForm) {
            closeBtn.addEventListener("click", () => {
                chatForm.classList.add("hidden");
                fetch("?closeChat=1");
            });
        }

        function scrollChatToBottom() {
            if (chatContent) {
                chatContent.scrollTop = chatContent.scrollHeight;
            }
        }

        if (chatForm && !chatForm.classList.contains("hidden")) {
            scrollChatToBottom();
        }

        // 1. Gửi tin nhắn bằng AJAX (Không bị reload trang)
        if (userForm && userInput) {
            userForm.addEventListener("submit", function(e) {
                e.preventDefault();
                const msgText = userInput.value.trim();
                if (!msgText) return;

                const formData = new FormData();
                formData.append("ajax_send_user_chat", "1");
                formData.append("message", msgText);

                fetch("index.php", {
                    method: "POST",
                    body: formData
                })
                .then(res => res.json())
                .then(data => {
                    if (data.success) {
                        userInput.value = "";
                        fetchUserMessages();
                    }
                })
                .catch(err => console.error("Send error:", err));
            });
        }

        // 2. Tự động lấy tin nhắn mới (Polling 2s)
        function fetchUserMessages() {
            if (!chatContent) return;
            fetch("index.php?ajax_get_user_chat=1")
            .then(res => res.json())
            .then(messages => {
                if (!Array.isArray(messages)) return;
                let html = "";
                messages.forEach(msg => {
                    if (msg.from === 'admin') {
                        html += `
                            <div class="d-flex align-items-start mb-2 flex-column">
                                <div class="d-flex" style="max-width: 80%;">
                                    <img src="data:image/jpeg;base64," class="rounded-circle me-2" style="width: 30px; height: 30px;">
                                    <div class="p-2 bg-light border rounded">
                                        ${escapeHtml(msg.message)}
                                    </div>
                                </div>
                                <div class="small text-muted" style="margin-left: 40px;">${msg.time || ''}</div>
                            </div>
                        `;
                    } else {
                        html += `
                            <div class="mb-2 text-end">
                                <div class="d-inline-block p-2 rounded bg-primary text-white" style="max-width: 80%; word-break: break-word; text-align: left;">
                                    ${escapeHtml(msg.message)}
                                </div>
                                <div class="small text-muted">${msg.time || ''}</div>
                            </div>
                        `;
                    }
                });
                chatContent.innerHTML = html;
                scrollChatToBottom();
            })
            .catch(err => console.error("Fetch user chat error:", err));
        }

        function escapeHtml(text) {
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Bật Polling 2 giây 1 lần
        setInterval(fetchUserMessages, 2000);
    });
</script>